local key="XENO_2026"
local hex=""

local function fromHex(h)
    local s=""
    for i=1,#h,2 do
        s=s..string.char(tonumber(h:sub(i,i+1),16))
    end
    return s
end

local function decrypt(data,k)
    local r=""
    for i=1,#data do
        local a=string.byte(data,i)
        local b=string.byte(k,(i-1)%#k+1)
        r=r..string.char((a-b)%256)
    end
    return r
end

loadstring(decrypt(fromHex(hex),key))()
